/* Sekreter renderer: 07-finance.js */
let MALI_HAREKETLER=[],OFIS_MALI_HAREKETLER=[],MALI_ORTAKLAR=[],MALI_AYARLAR=[],MALI_MAKBUZLAR=[];
async function maliSekmesiniAc(el){
  if(!_buro||!['yonetici','ortak'].includes(_buro.rol)){alert('Mali Takip yalnızca büro yöneticisi ve ortaklar tarafından kullanılabilir.');return;}
  await guvenlikOlayiKaydet('mali_alan_acildi',true);
  showView('mali',el);
}
let AKTIF_MALI_ALT_SEKME='genel';
function maliAltSekmeAc(ad,btn){AKTIF_MALI_ALT_SEKME=ad||'genel';document.querySelectorAll('.mali-alt-panel').forEach(x=>x.style.display=x.dataset.maliPanel===AKTIF_MALI_ALT_SEKME?'block':'none');document.querySelectorAll('[data-mali-tab]').forEach(x=>{const aktif=x.dataset.maliTab===AKTIF_MALI_ALT_SEKME;x.style.background=aktif?'var(--navy)':'var(--surface)';x.style.color=aktif?'white':'var(--text)';x.style.borderColor=aktif?'var(--navy)':'var(--border2)';});if(!btn)document.querySelector(`[data-mali-tab="${AKTIF_MALI_ALT_SEKME}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'});}
async function maliTakipYukle(){
  const hata=document.getElementById('mali-hata');if(hata)hata.textContent='';
  await buroKartlariYukle();
  const[d,o,or,a,mb]=await Promise.all([sb.from('dosya_mali_hareketleri').select('*').eq('buro_id',_buro.id).order('tarih',{ascending:false}),sb.from('ofis_mali_hareketleri').select('*').eq('buro_id',_buro.id).order('tarih',{ascending:false}),sb.from('mali_ortaklar').select('*').eq('buro_id',_buro.id).order('sira'),sb.from('mali_ay_ayarlari').select('*').eq('buro_id',_buro.id),sb.from('mali_makbuzlar').select('*').eq('buro_id',_buro.id).order('tarih',{ascending:false})]);
  if(d.error){if(hata)hata.textContent='Mali takip yüklenemedi: '+d.error.message;MALI_HAREKETLER=[];}else MALI_HAREKETLER=d.data||[];
  if(o.error){if(hata)hata.textContent='Ortaklık mali kurulumu bekleniyor.';OFIS_MALI_HAREKETLER=[];MALI_ORTAKLAR=[];MALI_AYARLAR=[];}else{OFIS_MALI_HAREKETLER=o.data||[];MALI_ORTAKLAR=or.data||[];MALI_AYARLAR=a.data||[];}MALI_MAKBUZLAR=mb.error?[]:mb.data||[];
  const ys=document.getElementById('mali-yil');if(ys&&!ys.options.length){const simdi=new Date().getFullYear(),yillar=[...new Set([simdi,...MALI_HAREKETLER.map(x=>Number(String(x.tarih).slice(0,4))).filter(Boolean)])].sort((a,b)=>b-a);ys.innerHTML=yillar.map(y=>`<option value="${y}">${y}</option>`).join('');}
  renderMaliTakip();maliAltSekmeAc(AKTIF_MALI_ALT_SEKME);
}
async function maliTakipYenile(btn){
  btn=btn||document.getElementById('mali-yenile-btn');const eski=btn?.innerHTML;
  if(btn){btn.disabled=true;btn.textContent='Yenileniyor…';}
  try{await maliTakipYukle();if(btn)btn.textContent='✓ Güncel';}
  catch(e){const hata=document.getElementById('mali-hata');if(hata)hata.textContent='Mali bilgiler yenilenemedi: '+(e?.message||e);if(btn)btn.textContent='Tekrar Dene';}
  finally{if(btn){setTimeout(()=>{btn.disabled=false;btn.innerHTML=eski||'↻ Yenile';},900);}}
}
function openOfisMaliFormu(tur,onKategori=''){const gelir=tur==='gelir',giderler=['Kira','Muhasebe','KDV','Stopaj','Gelir Vergisi','Damga Vergisi','Personel','Yakıt','Kırtasiye','Ulaşım','Kart / Aidat','Diğer'];let o=document.getElementById('ofis-mali-overlay');if(!o){o=document.createElement('div');o.id='ofis-mali-overlay';o.className='modal-overlay';o.style.zIndex='560';document.body.appendChild(o);}const kategoriler=gelir?['Dosyasız İş / Danışmanlık','CMK','Tevkil']:giderler;o.innerHTML=`<div class="modal" style="max-width:470px;"><div class="modal-header"><h2>${gelir?'Gelir':'Gider'} Ekle</h2><button class="btn" onclick="document.getElementById('ofis-mali-overlay').style.display='none'">✕</button></div><div class="modal-body"><div class="fg"><label>Kategori</label><select id="ofis-mali-kategori" onchange="ofisMaliKategoriDegisti()">${kategoriler.map(x=>`<option ${x===onKategori?'selected':''}>${x}</option>`).join('')}</select></div><div class="fg" id="ofis-mali-ortak-box" style="display:none;"><label>Gelir sahibi</label><select id="ofis-mali-ortak"><option value="">Ortak seçin</option>${MALI_ORTAKLAR.map(x=>`<option value="${x.id}">${esc(x.ad)}</option>`).join('')}</select></div>${gelir?'<div class="fg"><label>Ödemeyi yapan kişi / kurum</label><input id="ofis-mali-kisi" placeholder="Müvekkil veya kurum adı"></div>':''}<div class="fg"><label>Tutar (₺)</label><input id="ofis-mali-tutar" type="number" min="0.01" step="0.01"></div><div class="fg"><label>Tarih</label><input id="ofis-mali-tarih" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="fg"><label>Açıklama</label><input id="ofis-mali-aciklama" placeholder="Yapılan iş veya ödeme açıklaması"></div><button class="save-btn" onclick="ofisMaliKaydet('${tur}')">Kaydet</button><div id="ofis-mali-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;o.style.display='flex';ofisMaliKategoriDegisti();}
function ofisMaliKategoriDegisti(){const k=document.getElementById('ofis-mali-kategori')?.value,b=document.getElementById('ofis-mali-ortak-box');if(b)b.style.display=['CMK','Tevkil'].includes(k)?'block':'none';}
const AYLIK_GIDER_KALEMLERI=['Kira','Muhasebe','KDV','Stopaj','Gelir Vergisi','Personel','Yakıt','Kırtasiye','Diğer'];
function aylikGiderOzelKalemleriniHazirla(){OFIS_MALI_HAREKETLER.filter(x=>x.tur==='gider').forEach(x=>{const ad=String(x.kategori||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toLocaleUpperCase('tr-TR'));if(ad&&!AYLIK_GIDER_KALEMLERI.some(k=>maliAramaNorm(k)===maliAramaNorm(ad)))AYLIK_GIDER_KALEMLERI.push(ad);});}
function giderKategoriAnahtari(k){return k.toLocaleLowerCase('tr-TR').replaceAll(' ','_');}
function openAylikGiderFormu(){let o=document.getElementById('aylik-gider-overlay');if(!o){o=document.createElement('div');o.id='aylik-gider-overlay';o.className='modal-overlay';o.style.zIndex='560';document.body.appendChild(o);}const bugun=new Date(),yil=Number(document.getElementById('mali-yil')?.value)||bugun.getFullYear(),ay=yil===bugun.getFullYear()?bugun.getMonth()+1:1;o.innerHTML=`<div class="modal" style="max-width:590px;"><div class="modal-header"><div><h2>Aylık Gider Girişi</h2><div style="font-size:11px;color:var(--text2);margin-top:3px;">Seçtiğiniz aya ait giderleri girin veya mevcut tutarları değiştirin.</div></div><button class="btn" onclick="document.getElementById('aylik-gider-overlay').style.display='none'">✕</button></div><div class="modal-body"><div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;"><div class="fg"><label>Yıl</label><select id="aylik-gider-yil" onchange="aylikGiderSatirlariniGetir()">${Array.from({length:5},(_,i)=>yil-2+i).map(y=>`<option ${y===yil?'selected':''}>${y}</option>`).join('')}</select></div><div class="fg"><label>Ay</label><select id="aylik-gider-ay" onchange="aylikGiderSatirlariniGetir()">${['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'].map((a,i)=>`<option value="${i+1}" ${i+1===ay?'selected':''}>${a}</option>`).join('')}</select></div></div><div id="aylik-gider-satirlari"></div><div style="font-size:10px;color:var(--text3);margin:7px 0 12px;">Boş veya sıfır bırakılan kalem seçili aydan silinir. Girilen tutarlar yalnızca seçili aya kaydedilir.</div><button id="aylik-gider-kaydet" class="save-btn" onclick="aylikGiderleriKaydet()">Aylık Giderleri Kaydet</button><div id="aylik-gider-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;o.style.display='flex';aylikGiderSatirlariniGetir();}
function aylikGiderSatirlariniGetir(){const yil=Number(document.getElementById('aylik-gider-yil')?.value),ay=Number(document.getElementById('aylik-gider-ay')?.value),c=document.getElementById('aylik-gider-satirlari');if(!c)return;const ayAdi=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'][ay-1];c.innerHTML=`<div style="padding:10px 12px;margin:8px 0 4px;border-radius:10px;background:var(--bg2);border:1px solid var(--border);font-size:11px;color:var(--text2);"><b style="color:var(--text);">Seçilen dönem: ${ayAdi} ${yil}</b><br>Yalnızca bu aya kayıtlı tutarlar gösterilir ve değişiklikler bu aya kaydedilir.</div>`+AYLIK_GIDER_KALEMLERI.map(k=>{const key=giderKategoriAnahtari(k),mevcut=OFIS_MALI_HAREKETLER.filter(x=>x.tur==='gider'&&x.kategori===key&&Number(String(x.tarih).slice(0,4))===yil&&Number(String(x.tarih).slice(5,7))===ay).reduce((n,x)=>n+Number(x.tutar),0);return `<div style="display:grid;grid-template-columns:minmax(120px,1fr) minmax(130px,170px);gap:9px;align-items:center;padding:7px 0;border-bottom:1px solid var(--border);"><div><b style="font-size:12px;">${k}</b><div style="font-size:9px;color:var(--text3);margin-top:2px;">${mevcut?'Bu aya kayıtlı':'Bu ay için boş'}</div></div><input class="aylik-gider-tutar" data-kategori="${k}" type="number" min="0" step="0.01" value="${mevcut||''}" placeholder="0,00 ₺"></div>`;}).join('');}
async function aylikGiderleriKaydet(){const yil=Number(document.getElementById('aylik-gider-yil').value),ay=Number(document.getElementById('aylik-gider-ay').value),msg=document.getElementById('aylik-gider-msg'),btn=document.getElementById('aylik-gider-kaydet'),satirlar=[...document.querySelectorAll('.aylik-gider-tutar')].map(x=>({kategori:x.dataset.kategori,tutar:Number(x.value)||0})),baslangic=`${yil}-${String(ay).padStart(2,'0')}-01`,sonrakiAy=ay===12?`${yil+1}-01-01`:`${yil}-${String(ay+1).padStart(2,'0')}-01`;btn.disabled=true;btn.textContent='Kaydediliyor...';for(const s of satirlar){const key=giderKategoriAnahtari(s.kategori),sil=await sb.from('ofis_mali_hareketleri').delete().eq('buro_id',_buro.id).eq('tur','gider').eq('kategori',key).gte('tarih',baslangic).lt('tarih',sonrakiAy);if(sil.error){msg.textContent='Hata: '+sil.error.message;btn.disabled=false;btn.textContent='Aylık Giderleri Kaydet';return;}if(s.tutar>0){const{error}=await sb.from('ofis_mali_hareketleri').insert({buro_id:_buro.id,tur:'gider',kategori:key,ortak_id:null,tutar:s.tutar,tarih:baslangic,aciklama:'Aylık toplu gider',created_by:_user.id});if(error){msg.textContent='Hata: '+error.message;btn.disabled=false;btn.textContent='Aylık Giderleri Kaydet';return;}}}document.getElementById('aylik-gider-overlay').style.display='none';await maliTakipYukle();}
async function aylikGiderKalemiEkle(){const ad=await metinGirisPenceresi({baslik:'Yeni Gider Kalemi',etiket:'Gider kaleminin adı',yerTutucu:'Örn. İnternet, aidat, temizlik…',zorunlu:true});if(!ad)return;if(!AYLIK_GIDER_KALEMLERI.some(x=>maliAramaNorm(x)===maliAramaNorm(ad)))AYLIK_GIDER_KALEMLERI.push(ad);aylikGiderSatirlariniGetir();}
function aylikGiderIciKalemButonuEkle(){const c=document.getElementById('aylik-gider-satirlari');if(!c||document.getElementById('aylik-gider-kalem-ekle'))return;const b=document.createElement('button');b.id='aylik-gider-kalem-ekle';b.type='button';b.className='btn';b.style.cssText='width:100%;margin:10px 0;';b.textContent='＋ Yeni Gider Kalemi Ekle';b.onclick=aylikGiderKalemiEkle;c.insertAdjacentElement('afterend',b);}
function openMakbuzFormu(id=null){let o=document.getElementById('makbuz-overlay');if(!o){o=document.createElement('div');o.id='makbuz-overlay';o.className='modal-overlay';o.style.zIndex='565';document.body.appendChild(o);}const x=id?MALI_MAKBUZLAR.find(m=>String(m.id)===String(id)):null,oran=Number(x?.tevkifat_orani)||0,oranlar=[[0,'Tevkifat yok'],[.2,'2/10'],[.3,'3/10'],[.4,'4/10'],[.5,'5/10'],[.7,'7/10'],[.9,'9/10'],[1,'10/10']];o.innerHTML=`<div class="modal" style="max-width:500px;"><div class="modal-header"><div><h2>Ortaklık Makbuzu ${x?'Düzenle':'Ekle'}</h2><div style="font-size:11px;color:var(--text2);margin-top:3px;">Makbuzu kesen ortağı ve varsa KDV tevkifatını belirtin.</div></div><button class="btn" onclick="document.getElementById('makbuz-overlay').style.display='none'">✕</button></div><div class="modal-body"><div class="fg"><label>Makbuzu kesen ortak</label><select id="makbuz-ortak"><option value="">Ortak seçin</option>${MALI_ORTAKLAR.map(p=>`<option value="${p.id}" ${String(p.id)===String(x?.ortak_id)?'selected':''}>${esc(p.ad)}</option>`).join('')}</select></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;"><div class="fg"><label>Tarih</label><input id="makbuz-tarih" type="date" value="${x?.tarih||new Date().toISOString().slice(0,10)}"></div><div class="fg"><label>Makbuz No</label><input id="makbuz-no" value="${esc(x?.makbuz_no||'')}"></div></div><div style="display:grid;grid-template-columns:1fr 110px;gap:9px;"><div class="fg"><label>KDV hariç matrah (₺)</label><input id="makbuz-matrah" type="number" min="0" step="0.01" value="${x?.matrah??''}" oninput="makbuzKdvHesapla()"></div><div class="fg"><label>KDV oranı (%)</label><input id="makbuz-kdv-oran" type="number" min="0" step="0.01" value="${x?.kdv_orani??20}" oninput="makbuzKdvHesapla()"></div></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;"><div class="fg"><label>Hesaplanan KDV (₺)</label><input id="makbuz-kdv" type="number" min="0" step="0.01" value="${x?.kdv_tutari??''}" oninput="makbuzTevkifatHesapla()"></div><div class="fg"><label>KDV tevkifat oranı</label><select id="makbuz-tevkifat-oran" onchange="makbuzTevkifatHesapla()">${oranlar.map(a=>`<option value="${a[0]}" ${Math.abs(oran-a[0])<.001?'selected':''}>${a[1]}</option>`).join('')}</select></div></div><div id="makbuz-tevkifat-ozet" style="padding:9px;background:var(--surface2);border-radius:8px;font-size:11px;margin-bottom:11px;"></div><div class="fg"><label>Açıklama</label><input id="makbuz-aciklama" value="${esc(x?.aciklama||'')}" placeholder="Müvekkil / iş açıklaması"></div><button class="save-btn" onclick="makbuzKaydet(${id?`'${id}'`:'null'})">${x?'Değişiklikleri Kaydet':'Makbuzu Kaydet'}</button><div id="makbuz-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;o.style.display='flex';makbuzTevkifatHesapla();}
function makbuzKdvHesapla(){const m=Number(document.getElementById('makbuz-matrah')?.value)||0,o=Number(document.getElementById('makbuz-kdv-oran')?.value)||0,k=document.getElementById('makbuz-kdv');if(k)k.value=(m*o/100).toFixed(2);makbuzTevkifatHesapla();}
function makbuzTevkifatHesapla(){const kdv=Number(document.getElementById('makbuz-kdv')?.value)||0,oran=Number(document.getElementById('makbuz-tevkifat-oran')?.value)||0,tevkifat=kdv*oran,o=document.getElementById('makbuz-tevkifat-ozet');if(o)o.innerHTML=`Tevkif edilen KDV: <b>${tl(tevkifat)}</b> · Ortaklıkça ödenecek net KDV: <b>${tl(kdv-tevkifat)}</b>`;}
async function makbuzKaydet(id=null){const ortak_id=document.getElementById('makbuz-ortak').value,tarih=document.getElementById('makbuz-tarih').value,matrah=Number(document.getElementById('makbuz-matrah').value),kdv_orani=Number(document.getElementById('makbuz-kdv-oran').value),kdv_tutari=Number(document.getElementById('makbuz-kdv').value),tevkifat_orani=Number(document.getElementById('makbuz-tevkifat-oran').value)||0,tevkifat_tutari=kdv_tutari*tevkifat_orani,msg=document.getElementById('makbuz-msg');if(!ortak_id||!tarih||matrah<0||kdv_tutari<0||!Number.isFinite(matrah)||!Number.isFinite(kdv_tutari)){msg.textContent='Ortak, tarih, matrah ve KDV bilgilerini kontrol edin.';return;}const veri={ortak_id,tarih,makbuz_no:document.getElementById('makbuz-no').value.trim()||null,aciklama:document.getElementById('makbuz-aciklama').value.trim()||null,matrah,kdv_orani,kdv_tutari,tevkifat_orani,tevkifat_tutari};const{error}=id?await sb.from('mali_makbuzlar').update(veri).eq('id',id):await sb.from('mali_makbuzlar').insert({...veri,buro_id:_buro.id,created_by:_user.id});if(error){msg.textContent='Hata: '+error.message;return;}document.getElementById('makbuz-overlay').style.display='none';await maliTakipYukle();maliAltSekmeAc('kdv');}
async function makbuzSil(id){if(!confirm('Bu makbuz kaydı silinsin mi?'))return;const{error}=await sb.from('mali_makbuzlar').delete().eq('id',id);if(error){alert('Hata: '+error.message);return;}await maliTakipYukle();}
function makbuzNetKdv(x){return Math.max(0,(Number(x.kdv_tutari)||0)-(Number(x.tevkifat_tutari)||0));}
function kdvMahsuplasmaHTML(makbuzlar){const toplam=makbuzlar.reduce((n,x)=>n+makbuzNetKdv(x),0),durum=MALI_ORTAKLAR.map(o=>{const kestigi=makbuzlar.filter(x=>String(x.ortak_id)===String(o.id)).reduce((n,x)=>n+makbuzNetKdv(x),0),payi=toplam*(Number(o.pay_orani)||0)/100;return{ad:o.ad,bakiye:kestigi-payi};}),alacakli=durum.filter(x=>x.bakiye>.005).map(x=>({...x})),borclu=durum.filter(x=>x.bakiye<-.005).map(x=>({...x,bakiye:-x.bakiye})),sat=[];let a=0,b=0;while(a<alacakli.length&&b<borclu.length){const tutar=Math.min(alacakli[a].bakiye,borclu[b].bakiye);sat.push(`<div style="margin-top:5px;color:#1d4ed8;"><b>${esc(borclu[b].ad)}</b>, <b>${esc(alacakli[a].ad)}</b> kişisine ${tl(tutar)} verir.</div>`);alacakli[a].bakiye-=tutar;borclu[b].bakiye-=tutar;if(alacakli[a].bakiye<.005)a++;if(borclu[b].bakiye<.005)b++;}return sat.length?sat.join(''):'<div style="margin-top:5px;color:var(--text3);">Bu ay ortaklar arasında KDV ödemesi yok.</div>';}
async function ofisMaliKaydet(tur){const kategori=document.getElementById('ofis-mali-kategori').value,tutar=Number(document.getElementById('ofis-mali-tutar').value),tarih=document.getElementById('ofis-mali-tarih').value,ortak=document.getElementById('ofis-mali-ortak').value||null,kisi=document.getElementById('ofis-mali-kisi')?.value.trim()||'',not=document.getElementById('ofis-mali-aciklama').value.trim(),aciklama=[kisi,not].filter(Boolean).join(' — '),msg=document.getElementById('ofis-mali-msg');if(!(tutar>0)||!tarih){msg.textContent='Geçerli tutar ve tarih girin.';return;}if(tur==='gelir'&&['CMK','Tevkil'].includes(kategori)&&!ortak){msg.textContent='CMK veya tevkil gelirinin sahibini seçin.';return;}if(kategori==='Dosyasız İş / Danışmanlık'&&!kisi){msg.textContent='Ödemeyi yapan kişi veya kurum adını yazın.';return;}const{error}=await sb.from('ofis_mali_hareketleri').insert({buro_id:_buro.id,tur,kategori:kategori.toLocaleLowerCase('tr-TR').replaceAll(' ','_'),ortak_id:ortak,tutar,tarih,aciklama:aciklama||null,created_by:_user.id});if(error){msg.textContent='Hata: '+error.message;return;}document.getElementById('ofis-mali-overlay').style.display='none';await maliTakipYukle();}
function maliKategoriAdi(k){return String(k||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toLocaleUpperCase('tr-TR'));}
